{
  "application": "poster-generation",
  "case_id": "case-env-climate-sclerosponge-thermometry-1.5C",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A0-portrait",
    "audience": "academic-conference",
    "tone": "academic, data-forward",
    "venue": "AGU / Nature Climate Change Symposium"
  },
  "brief": {
    "title": "300 Years of Sclerosponge Thermometry Shows Global Warming Has Exceeded 1.5 °C",
    "one_liner": "Sclerosponge-derived ocean temperature records spanning three centuries reveal that anthropogenic warming has already surpassed the critical 1.5 °C Paris Agreement threshold when measured against a true pre-industrial baseline.",
    "goal": "Convey to the scientific community that conventional instrumental records underestimate total warming because they start too late, and that sclerosponge proxies push the estimated warming ~0.5 °C higher, meaning 1.5 °C has already been exceeded."
  },
  "sections": [
    {
      "id": "background",
      "title": "Why Sclerosponges?",
      "objective": "Explain the proxy method: sclerosponges incorporate Sr/Ca ratios that track sea-surface temperature, providing continuous records back to ~1700 CE — well before instrumental coverage."
    },
    {
      "id": "key-finding",
      "title": "Pre-Industrial Baseline Matters",
      "objective": "Show that the IPCC's 1850–1900 reference period already contained ~0.5 °C of anthropogenic warming, so total warming from a true pre-industrial baseline is substantially higher than commonly reported."
    },
    {
      "id": "temperature-timeline",
      "title": "300-Year Temperature Reconstruction",
      "objective": "Present the reconstructed temperature anomaly timeline from ~1700 to present, highlighting the inflection points and the crossing of the 1.5 °C threshold."
    },
    {
      "id": "implications",
      "title": "Policy & Climate Target Implications",
      "objective": "Discuss what exceeding 1.5 °C means for Paris Agreement targets, remaining carbon budgets, and the urgency of mitigation action."
    },
    {
      "id": "methods",
      "title": "Data & Methods",
      "objective": "Briefly summarize sclerosponge sampling locations, Sr/Ca calibration, and comparison with HadCRUT5 and other instrumental datasets."
    }
  ],
  "metrics": [
    {
      "label": "Record Length",
      "value": "~300 years (back to ~1700 CE)"
    },
    {
      "label": "Hidden Pre-Industrial Warming",
      "value": "~0.5 °C already present by 1850–1900"
    },
    {
      "label": "Total Warming (True Pre-Industrial)",
      "value": ">1.5 °C exceeded by early 2020s"
    },
    {
      "label": "IPCC-Reported Warming (1850–1900 baseline)",
      "value": "~1.2 °C as of 2020"
    },
    {
      "label": "Proxy Source",
      "value": "Sr/Ca ratios in Caribbean sclerosponge skeletons"
    }
  ]
}

