<script src="/app/vendor/infographic.min.js"></script>
<script>
  const infographic = new AntVInfographic.Infographic({
    container: '#container',
    width: '100%',
    height: '100%',
  });

  const syntax = `infographic list-column-vertical-icon-arrow
data
  title 300 Years of Sclerosponge Thermometry Shows Global Warming Has Exceeded 1.5 °C
  desc A landmark finding in climate science: sclerosponge-based temperature proxies spanning 300 years reveal that global warming has already exceeded the Paris Agreement's 1.5 °C threshold — roughly 0.5 °C more than conventional instrumental records suggest.
  lists
    - label Why Sclerosponges?
      desc Sclerosponges are long-lived marine organisms whose Sr/Ca ratios track sea-surface temperature, providing continuous annual-resolution records back to ~1700 CE — well before instrumental coverage.
      icon ocean sea
    - label Key Finding: Pre-Industrial Baseline Matters
      desc The IPCC's 1850–1900 reference period already contained ~0.5 °C of anthropogenic warming. Total warming from a true pre-industrial baseline is substantially higher than commonly reported.
      icon chart line
    - label Temperature Timeline (Centerpiece)
      desc 300-year reconstruction from ~1700 to present showing anomaly curve with 1.5 °C threshold crossing highlighted. Stable pre-industrial temps (1700–1790), onset of warming (1790–1850), 0.5 °C already present by 1850–1900, acceleration (1960–2000), and >1.5 °C exceeded by early 2020s.
      icon timeline
    - label Policy Implications
      desc Paris Agreement's 1.5 °C target uses 1850–1900 baseline — not truly pre-industrial. Sclerosponge-informed baseline reduces remaining carbon budget for 1.5 °C to effectively zero. Even 2.0 °C guardrail is closer than estimated (~0.3 °C vs ~0.8 °C remaining).
      icon policy document
    - label Data & Methods
      desc Caribbean sclerosponge specimens (33–91 m depth). Sr/Ca ratios measured via ICP-OES, calibrated against instrumental SST (r² > 0.9). Validated against HadCRUT5 and NOAA ERSSTv5.
      icon laboratory science
theme
  palette #1a365d #2b6cb0 #4299e1 #48bb78 #ed8936 #e53e3e
`;

  document.fonts?.ready.then(() => {
    infographic.render(syntax);
  }).catch((error) => console.error('Error waiting for fonts to load:', error));

  infographic.render(syntax);

  // Export SVG after render
  setTimeout(async () => {
    try {
      const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
      console.log('SVG export available at:', svgDataUrl);
    } catch (e) {
      console.log('SVG export not yet available');
    }
  }, 2000);
</script>
", "structuredPatch": [], "originalFile": null, "userModified": false}

