const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'poster-render.html');
  await page.goto(`file://${htmlPath}`);

  // Wait for infographic to render
  await page.waitForTimeout(3000);

  // Get the poster container and screenshot it
  const posterElement = await page.$('#poster-container');
  const screenshot = await posterElement.screenshot({
    type: 'png',
    path: '/app/output/final_poster.png',
    fullPage: false
  });

  console.log('Poster saved to /app/output/final_poster.png');

  await browser.close();
})();

